nta.declaration:
// MAP BOUNDARIES
const int MAX_X = 17;        // The rightmost cell boundary.
const int MAX_Y = 12;        // The topmost cell boundary (home bays).
const int MIN_X = 0;         // The leftmost boundary.
const int MIN_Y = 0;         // The bottommost boundary.

// TIMERS (1 time unit = 0.1s)
const int INITIAL_TIMEOUT = 300; // 30 seconds
const int RESPAWN_DELAY = 20;    // 2 seconds
const int MOVE_DELAY = 1;        // 1 time unit to prevent Zeno behaviors
const int TURTLE_EMERGED_TIME = 100; 
const int TURTLE_DIVING_TIME = 50;
const int TURTLE_SUBMERGED_TIME = 100;
const int TURTLE_EMERGING_TIME = 50;

// FROG
int[0, MAX_X] frog_x = 9;    // Frogger's current X position.
int[0, MAX_Y] frog_y = 0;    // Frogger's current Y position.

// GAME PROGRESSION
int[0, 5] lives = 5;                // The player starts with 5 lives.
int score = 0;                      // Total points scored.
int[0, 5] home_bays_filled = 0;     // Tracks how many of the 5 bays are occupied.
bool bay_occupied[5];               // An array tracking which specific bays are filled (Indices 0 to 4 mapping to the 5 home bay pairs).

// DANGER ZONES
bool danger[MAX_X + 1][MAX_Y + 1];            // Vehicles update their current footprint to true here. If Frogger is on a true tile, he dies.
bool safe_platform[MAX_X + 1][MAX_Y + 1];     // Logs and Turtles update their footprint here. If Frogger is in the river (Y = 7 to 11) and this is false, he drowns.

// CHANNELS
broadcast chan die;        // Triggered when Frogger touches a vehicle, submerging turtle, or drowns.

template.declaration:
clock c;
int current_x;

// Updates the danger map for the vehicle's footprint
void update_footprint(bool is_danger) {
    int i;
    int px;

    for (i = 0; i < size; i++) {
        px = current_x + i;
        // Only update if it is currently within the visible screen
        if (px >= 0 && px <= MAX_X) {
            danger[px][y_row] = is_danger;
        }
    }
}

void move() {
    update_footprint(false); // Clear old position

    if (y_row % 2 != 0) { 
        // Odd rows move Right to Left
        current_x--;
        // Reappear on the opposite side after 2 cell delay
        if (current_x < -2) {
            current_x = MAX_X;
        }
    } else { 
        // Even rows move Left to Right
        current_x++;
        if (current_x > MAX_X + 2) {
            current_x = -size; // Start sliding in from the left
        }
    }

    update_footprint(true);  // Draw new position
}

clock c;
int current_x;

// Updates the safe_platform map for the object's footprint
void update_footprint(bool is_safe) {
    int i;
    int px;

    for (i = 0; i < size; i++) {
        px = current_x + i;
        // Only update if it is currently within the visible screen
        if (px >= 0 && px <= MAX_X) {
            safe_platform[px][y_row] = is_safe;
        }
    }
}

void move() {
    // Check if Frogger is standing on this specific object BEFORE it moves
    bool carrying_frog = (frog_y == y_row && frog_x >= current_x && frog_x < current_x + size);

    update_footprint(false); // Clear old position

    // Move Left to Right (Rows 8, 9, 11)
    if (y_row == 8 || y_row == 9 || y_row == 11) {
        current_x++;

        // Object wrap-around
        if (current_x > MAX_X + 2) {
            current_x = -size; 
        }

        // Carry Frogger and handle his wrap-around
        if (carrying_frog) {
            frog_x++;
            if (frog_x > MAX_X) {
                frog_x = 0; 
            }
        }
    } 
    // Move Right to Left (Rows 7, 10)
    else { 
        current_x--;

        // Object wrap-around
        if (current_x < -2) {
            current_x = MAX_X;
        }

        // Carry Frogger and handle his wrap-around
        if (carrying_frog) {
            frog_x--;
            if (frog_x < 0) {
                frog_x = MAX_X; 
            }
        }
    }

    update_footprint(true);  // Draw new position
}

clock c;
clock timer;
int current_x;
bool submerged = false; // Tracks if the turtle is underwater

// Helper to check if Frogger is standing on THIS specific turtle
bool carrying_frog() {
    return (frog_y == y_row && frog_x >= current_x && frog_x < current_x + size);
}

void update_footprint(bool is_safe) {
    int i;
    int px;

    for (i = 0; i < size; i++) {
        px = current_x + i;
        if (px >= 0 && px <= MAX_X) {
            safe_platform[px][y_row] = is_safe;
        }
    }
}

void move() {
    bool has_frog = carrying_frog();
    update_footprint(false); // Clear old position

    // Diving turtles only exist on rows 7 and 10, which move Right to Left
    current_x--;
    if (current_x < -2) {
        current_x = MAX_X;
    }

    // Carry Frogger and wrap him around
    if (has_frog) {
        frog_x--;
        if (frog_x < 0) {
            frog_x = MAX_X;
        }
    }

    // Only draw the new footprint if the turtle is NOT currently submerged
    if (!submerged) {
        update_footprint(true);
    }
}

clock game_timer;            
clock time_since_respawn;    

// Used to respawn Frogger in its original position
void reposition() {
    frog_x = 9;
    frog_y = 0;
}

// Is Frogger currently in the river?
bool is_in_river() {
    return (frog_y >= 7 && frog_y <= 11);
}

// Did Frogger land on something that kills him?
bool is_deadly() {
    // Road collision
    if (danger[frog_x][frog_y] == true) return true;

    // Drowned in the river
    if (is_in_river() && safe_platform[frog_x][frog_y] == false) return true;

    // Smashed into the green wall between home bays
    if (frog_y == MAX_Y && (frog_x % 4 >= 2)) return true;

    return false;
}

// Did Frogger successfully reach an empty home bay?
bool is_home_bay() {
    // The top row is MAX_Y (12). The bays are only on X coordinates where X % 4 < 2.
    return (frog_y == MAX_Y && (frog_x % 4 < 2));
}

// Is Frogger physically allowed to jump up?
bool can_jump() {
    // Prevent jumping out of the map bounds entirely
    if (frog_y >= MAX_Y) return false;

    // If we are at Y=MAX_Y-1 (right below the bays), we must check the target cell
    if (frog_y == MAX_Y - 1) {
        // Only block the jump if he is aiming at a valid bay AND it is full
        if ((frog_x % 4 < 2) && bay_occupied[frog_x / 4] == true) {
            return false;
        }
    }

    return true;
}

nta.system:
OrangeCar1 = Vehicle(1, 3, 4, 1);
OrangeCar2 = Vehicle(1, 3, 14, 1);
Bulldozer1 = Vehicle(1, 10, 2, 2);
Bulldozer2 = Vehicle(1, 10, 11, 2);

DivingTurtles7_1 = DivingTurtles(1, 6, 13, 7);
DivingTurtles7_2 = DivingTurtles(1, 6, 15, 7);
DivingTurtles7_3 = DivingTurtles(1, 6, 17, 7);

Log8_1 = FloatingObject(3, 2, 7, 8);
Log8_2 = FloatingObject(3, 2, 11, 8);
Log8_3 = FloatingObject(3, 2, 15, 8);
Log9_1 = FloatingObject(9, 7, 3, 9);

system OrangeCar1, OrangeCar2, Bulldozer1, Bulldozer2, DivingTurtles7_1, DivingTurtles7_2, DivingTurtles7_3, Log8_1, Log8_2, Log8_3, Log9_1;
